  const port = server.address().port;

  const data = JSON.stringify({
    rule: 'ctx.amount > 100',
    context: { amount: 150 }
  });

  const options = {
    hostname: 'localhost',
    port: port,
    path: '/check',
    method: 'POST',
    headers: { 'Content-Type': 'application/json' }
  };

  const req = http.request(options, (res) => {
    let body = '';
    res.on('data', chunk => body += chunk);
    res.on('end', () => {
      console.log('Response:', body);
      server.close();
    });
  });

  req.write(data);
  req.end();
});
"

